const fs = require('bare-fs')
const path = require('bare-path')
const { pathToFileURL, fileURLToPath } = require('bare-url')
const Module = require('bare-module')
const b4a = require('b4a')

module.exports = code_to_drive

// copies a js file and everything it requires from disk into a drive, so drive-loader can run it from there
// the files are found by linking the file with bare-module without running it, so the drive gets exactly what the loader needs
// files inside a node_modules folder go to /node_modules/..., the rest keeps its path next to the entry file
// files above the entry folder (like the project package.json the loader checks for its type) are not copied
async function code_to_drive ({ drive, file, builtins = {} }) {
  const files = new Set()
  const protocol = new Module.Protocol({ exists, read })
  const loader = new Module.Loader({ protocol, builtins, defaultType: Module.constants.SCRIPT })
  await loader.link(pathToFileURL(file))
  for (const source of files) {
    const target = drive_path(source, path.dirname(file))
    if (target) await copy_file({ drive, source, target })
  }
  return drive_path(path.resolve(file), path.dirname(file))

  function exists (url) { return fs.existsSync(fileURLToPath(url)) && fs.statSync(fileURLToPath(url)).isFile() }

  function read (url) {
    files.add(fileURLToPath(url))
    return fs.readFileSync(fileURLToPath(url))
  }
}

/***************************************
DRIVE PATH
where a file from disk goes in the drive, null if it is above the entry folder
***************************************/
function drive_path (source, root) {
  const at = source.indexOf('/node_modules/')
  if (at !== -1) return source.slice(at)
  const relative = path.relative(path.resolve(root), source)
  return relative.startsWith('..') ? null : '/' + relative
}

/***************************************
COPY FILE
puts a file into the drive, skipped if the drive already has the same bytes
***************************************/
async function copy_file ({ drive, source, target }) {
  const data = fs.readFileSync(source)
  const old = await drive.get(target)
  if (!old || !b4a.equals(old, data)) await drive.put(target, data)
}
